CREATE FUNCTION mercado.validar_conteudo() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, mercado AS $$
DECLARE
  versao mercado.versoes_dados%ROWTYPE;
BEGIN
  SELECT * INTO versao FROM mercado.versoes_dados WHERE versao_dados = NEW.versao_dados FOR UPDATE;
  IF NOT FOUND OR versao.estado <> 'preparacao' THEN
    RAISE EXCEPTION 'Conteúdo exige versão em preparação' USING ERRCODE = '23514';
  END IF;
  IF TG_TABLE_NAME = 'precos' THEN
    IF NOT (NEW.semana BETWEEN versao.primeira_semana AND versao.ultima_semana OR NEW.semana = versao.semana_anterior) THEN
      RAISE EXCEPTION 'Semana fora da versão' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
