CREATE FUNCTION mercado.validar_versao() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, mercado AS $$
DECLARE
  quantidade_perfis bigint;
  quantidade_regioes bigint;
  quantidade_municipios bigint;
  quantidade_precos bigint;
  precos_janela bigint;
  precos_anterior bigint;
  semanas integer;
  condicoes jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.estado <> 'preparacao' OR NEW.publicado_em IS NOT NULL THEN
      RAISE EXCEPTION 'Versão deve começar em preparação sem instante' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.estado <> 'preparacao' OR NEW.estado <> 'publicada'
     OR NEW.publicado_em IS NOT NULL
     OR (to_jsonb(NEW) - 'estado' - 'publicado_em') IS DISTINCT FROM (to_jsonb(OLD) - 'estado' - 'publicado_em') THEN
    RAISE EXCEPTION 'Somente a finalização imutável é permitida' USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO quantidade_perfis FROM mercado.perfis WHERE versao_dados = NEW.versao_dados;
  SELECT count(*) INTO quantidade_regioes FROM mercado.regioes WHERE versao_dados = NEW.versao_dados;
  SELECT count(*) INTO quantidade_municipios FROM mercado.municipios WHERE versao_dados = NEW.versao_dados;
  SELECT count(*), count(*) FILTER (WHERE semana BETWEEN NEW.primeira_semana AND NEW.ultima_semana),
    count(*) FILTER (WHERE semana = NEW.semana_anterior)
    INTO quantidade_precos, precos_janela, precos_anterior
    FROM mercado.precos WHERE versao_dados = NEW.versao_dados;
  SELECT jsonb_agg(jsonb_build_object('id', condicoes_id, 'pagamento', pagamento, 'frete', frete, 'tributos', tributos, 'descricao', descricao) ORDER BY condicoes_id)
    INTO condicoes FROM mercado.condicoes_comerciais WHERE versao_dados = NEW.versao_dados;
  semanas := (NEW.ultima_semana - NEW.primeira_semana) / 7 + 1;

  IF quantidade_perfis <> 8 OR quantidade_regioes <> 10 OR jsonb_array_length(condicoes) IS DISTINCT FROM 1
    OR NOT EXISTS (SELECT 1 FROM mercado.condicoes_comerciais WHERE versao_dados = NEW.versao_dados AND condicoes_id = 'avista-sem-frete-sem-tributos')
    OR EXISTS (SELECT 1 FROM mercado.regioes r WHERE r.versao_dados = NEW.versao_dados
       AND NOT EXISTS (SELECT 1 FROM mercado.municipios m WHERE m.versao_dados = r.versao_dados AND m.regiao_id = r.regiao_id)) THEN
    RAISE EXCEPTION 'Cadastros incompletos' USING ERRCODE = '23514';
  END IF;

  -- Containment retains audit-only fields while requiring every normalized value,
  -- including numeric counts, to be present with its correct JSON type.
  IF NOT (NEW.manifesto @> jsonb_build_object(
    'versaoDados', NEW.versao_dados, 'conjuntoId', NEW.conjunto_id,
    'versaoFormatoArquivos', NEW.versao_formato_arquivos, 'natureza', NEW.natureza,
    'versaoTerritorial', NEW.versao_territorial, 'preparadoEm', to_char(NEW.preparado_em, 'YYYY-MM-DD'),
    'janela', jsonb_build_object('inicio', to_char(NEW.janela_inicio, 'YYYY-MM-DD'), 'fim', to_char(NEW.janela_fim, 'YYYY-MM-DD'),
      'primeiraSemana', to_char(NEW.primeira_semana, 'YYYY-MM-DD'), 'ultimaSemana', to_char(NEW.ultima_semana, 'YYYY-MM-DD'),
      'semanaAnterior', to_char(NEW.semana_anterior, 'YYYY-MM-DD'), 'diaReferencia', 'segunda-feira',
      'quantidadeSemanasNaJanela', semanas, 'quantidadeSemanasComAnterior', semanas + 1),
    'contagens', jsonb_build_object('perfis', quantidade_perfis, 'regioes', quantidade_regioes, 'municipios', quantidade_municipios,
      'precos', quantidade_precos, 'precosNaJanela', precos_janela, 'precosSemanaAnterior', precos_anterior,
      'combinacoesPossiveis', (semanas + 1) * 80, 'lacunas', (semanas + 1) * 80 - quantidade_precos)))
    OR (NEW.manifesto -> 'condicoesComerciais') IS DISTINCT FROM condicoes THEN
    RAISE EXCEPTION 'Manifesto incompatível com metadados ou contagens' USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(NEW.manifesto -> 'referencias') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Manifesto sem referências' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.manifesto -> 'referencias') r WHERE r ->> 'id' = NEW.versao_territorial)
    OR EXISTS (SELECT 1 FROM mercado.perfis p WHERE p.versao_dados = NEW.versao_dados
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.manifesto -> 'referencias') r WHERE r ->> 'id' = p.referencia_parametros_id)) THEN
    RAISE EXCEPTION 'Referência de fonte ausente no manifesto' USING ERRCODE = '23514';
  END IF;

  NEW.publicado_em := clock_timestamp()::timestamptz(3);
  RETURN NEW;
END;
$$;
