CREATE FUNCTION mercado.exigir_finalizacao() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, mercado AS $$
BEGIN
  -- NEW belongs to INSERT. Read final transactional state instead.
  IF NOT EXISTS (SELECT 1 FROM mercado.versoes_dados WHERE versao_dados = NEW.versao_dados AND estado = 'publicada') THEN
    RAISE EXCEPTION 'Transação não finalizou a versão' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END;
$$;
