CREATE FUNCTION mercado.validar_ponteiro() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, mercado AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.versao_dados IS NULL
    OR NOT EXISTS (SELECT 1 FROM mercado.versoes_dados WHERE versao_dados = NEW.versao_dados AND estado = 'publicada') THEN
    RAISE EXCEPTION 'Ponteiro exige versão publicada e identidade permanente' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;
